练习http://47.121.118.174/p/80#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longconst int N=2e5+10,B=131,P=998244353;ll pre[N],base[N];int n,q;string s;void init()&#123;    base[0]=1;    n=s.size();    for(int i=1;i&lt;=n;i++)&#123;        base[i]=base[i-1]*B%P;        pre[i]=(pre[i-1]*B+s[i])%P;    &#125;&#125;ll get_hash(int l,int r)&#123;    return (pre[r]-pre[l-1]*base[r-l+1]%P+P)%P;&#125;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    cin &gt;&gt; n &gt;&gt; q &gt;&gt; s;     s=&quot; &quot;+s;    init();    for(int i=1;i&lt;=q;i++)&#123;        int l1,l2,r1,r2;        cin &gt;&gt; l1 &gt;&gt; r1 &gt;&gt; l2 &gt;&gt; r2;        if(get_hash(l1,r1)==get_hash(l2,r2)) cout &lt;&lt; &quot;Yes\n&quot;;        else cout &lt;&lt; &quot;No\n&quot;;            &#125;            return 0;&#125;

