http://47.121.118.174/p/81题干说卡了单哈希做法的常见底数与模数。所以我们改用双哈希。
双哈希也很简单喵。就是算两次哈希，两次比较都通过了才算过。
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longconst int N = 2e5 + 5,B=131,P=998244353,B2=13331,P2=1000000007;ll pre[N],base[N],base2[N],pre2[N];int n,q;string s,s1;void init()&#123;    base[0]=1;    base2[0]=1;    for(int i=1;i&lt;=n;i++)&#123;        base[i]=base[i-1]*B%P;        pre[i]=(pre[i-1]*B+s[i])%P;        base2[i]=base2[i-1]*B2%P2;        pre2[i]=(pre2[i-1]*B2+s[i])%P2;    &#125;&#125;ll get_hash(int l,int r)&#123;    return (pre[r]-pre[l-1]*base[r-l+1]%P+P)%P;&#125;ll get_hash2(int l,int r)&#123;    return (pre2[r]-pre2[l-1]*base2[r-l+1]%P2+P2)%P2;&#125;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        cin &gt;&gt; n &gt;&gt; q;    cin &gt;&gt; s;    s=&quot; &quot; + s;    init();    while(q--)&#123;        int l1,r1,l2,r2;        cin &gt;&gt; l1 &gt;&gt; r1 &gt;&gt; l2 &gt;&gt; r2;        if(get_hash(l1,r1)==get_hash(l2,r2) &amp;&amp; get_hash2(l1,r1)==get_hash2(l2,r2)) cout &lt;&lt; &quot;Yes\n&quot;;        else cout &lt;&lt; &quot;No\n&quot;;    &#125;            return 0;&#125;

